// Publicacion Diaria 00:00 por Ciudad en Facebook Page + Instagram Business
// Primera imagen del carrusel: Portada de la ciudad con la fecha actual de publicacion
// Siguientes imagenes: Tarjetas de todos los inmuebles aprobados de esa ciudad
const rawInput = $input.first().json.body || $input.first().json;

const pageId = $env.META_PAGE_ID;
const igUserId = $env.META_IG_USER_ID;
const accessToken = $env.META_PAGE_ACCESS_TOKEN;
const webhookSecret = $env.N8N_WEBHOOK_SECRET;

// Normalizar si viene del lote diario por ciudades (/n8n/daily-diffusions) o de un webhook individual
let cityBatches = [];
if (Array.isArray(rawInput.cities)) {
  cityBatches = rawInput.cities;
} else if (rawInput.difusion_id) {
  const city = rawInput.ciudad || 'Bolivia';
  const encodedCity = encodeURIComponent(city);
  const pubBase = (rawInput.imagen_generada_jpg_url || rawInput.imagen_generada_url || '').split('/public/')[0];
  const intBase = (rawInput.imagen_generada_internal_jpg_url || rawInput.imagen_generada_internal_url || pubBase).split('/public/')[0];
  const coverPub = `${pubBase}/public/diffusions/city-cover/${encodedCity}/social-card.jpg?count=1`;
  const coverInt = `${intBase}/public/diffusions/city-cover/${encodedCity}/social-card.jpg?count=1`;
  const cardPub = rawInput.imagen_generada_jpg_url || rawInput.imagen_generada_url;
  const cardInt = rawInput.imagen_generada_internal_jpg_url || rawInput.imagen_generada_internal_url || cardPub;

  cityBatches = [
    {
      city,
      diffusionIds: [rawInput.difusion_id],
      carouselImagesJpg: [coverPub, cardPub],
      carouselImagesInternalJpg: [coverInt, cardInt],
      cityCaption: rawInput.caption_redes || rawInput.texto_post || '',
      callbackUrl: rawInput.callback_url,
    },
  ];
}

if (!cityBatches.length) {
  return [];
}

const results = [];

for (const batch of cityBatches) {
  const errors = [];
  let fbPostId = null;
  let igMediaId = null;

  const publicUrls = Array.isArray(batch.carouselImagesJpg) ? batch.carouselImagesJpg : [];
  const internalUrls = Array.isArray(batch.carouselImagesInternalJpg) && batch.carouselImagesInternalJpg.length === publicUrls.length
    ? batch.carouselImagesInternalJpg
    : publicUrls;
  const caption = (batch.cityCaption || '').trim();

  if (!accessToken) {
    errors.push('Falta configurar META_PAGE_ACCESS_TOKEN en las variables de entorno de n8n');
  } else if (publicUrls.length === 0) {
    errors.push(`No hay imagenes para publicar en la ciudad ${batch.city}`);
  } else {
    // 1. FACEBOOK PAGE: Subir cada imagen (Portada Ciudad + Fecha actual primero, luego fichas) como unpublished y publicar carrusel/album
    if (pageId) {
      try {
        const mediaFbIds = [];
        for (let i = 0; i < publicUrls.length; i++) {
          const pubUrl = publicUrls[i];
          const intUrl = internalUrls[i] || pubUrl;
          const isLocal = /localhost|127\.0\.0\.1|backend:|tuapp\.com/i.test(pubUrl);
          let photoRes = null;

          if (!isLocal) {
            try {
              photoRes = await this.helpers.httpRequest({
                method: 'POST',
                url: `https://graph.facebook.com/v21.0/${pageId}/photos`,
                body: {
                  url: pubUrl,
                  published: false,
                  access_token: accessToken,
                },
                json: true,
              });
            } catch (e) {
              photoRes = null;
            }
          }

          if (!photoRes || !photoRes.id) {
            const imgBuffer = await this.helpers.httpRequest({
              method: 'GET',
              url: intUrl,
              encoding: null,
            });

            photoRes = await this.helpers.httpRequest({
              method: 'POST',
              url: `https://graph.facebook.com/v21.0/${pageId}/photos`,
              formData: {
                published: 'false',
                access_token: accessToken,
                source: {
                  value: imgBuffer,
                  options: {
                    filename: `alquilabo-${batch.city}-${i}.jpg`,
                    contentType: 'image/jpeg',
                  },
                },
              },
              json: true,
            });
          }

          if (photoRes && photoRes.id) {
            mediaFbIds.push({ media_fbid: photoRes.id });
          }
        }

        if (mediaFbIds.length > 0) {
          const feedRes = await this.helpers.httpRequest({
            method: 'POST',
            url: `https://graph.facebook.com/v21.0/${pageId}/feed`,
            body: {
              message: caption,
              attached_media: mediaFbIds,
              access_token: accessToken,
            },
            json: true,
          });
          fbPostId = feedRes.id || feedRes.post_id || null;
        }
      } catch (err) {
        errors.push(`Facebook (${batch.city}): ${err.message || String(err)}`);
      }
    }

    // 2. INSTAGRAM BUSINESS: Publicar Carrusel (hasta 10 imagenes por post de ciudad, primera = portada ciudad + fecha)
    if (igUserId) {
      try {
        const igImages = publicUrls.slice(0, 10);
        if (igImages.length === 1) {
          const singleContainer = await this.helpers.httpRequest({
            method: 'POST',
            url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
            body: {
              image_url: igImages[0],
              caption,
              access_token: accessToken,
            },
            json: true,
          });
          if (singleContainer && singleContainer.id) {
            const publishRes = await this.helpers.httpRequest({
              method: 'POST',
              url: `https://graph.facebook.com/v21.0/${igUserId}/media_publish`,
              body: {
                creation_id: singleContainer.id,
                access_token: accessToken,
              },
              json: true,
            });
            igMediaId = publishRes.id || null;
          }
        } else {
          const childIds = [];
          for (const imgUrl of igImages) {
            const childRes = await this.helpers.httpRequest({
              method: 'POST',
              url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
              body: {
                image_url: imgUrl,
                is_carousel_item: true,
                access_token: accessToken,
              },
              json: true,
            });
            if (childRes && childRes.id) {
              childIds.push(childRes.id);
            }
          }

          if (childIds.length > 0) {
            const carouselContainer = await this.helpers.httpRequest({
              method: 'POST',
              url: `https://graph.facebook.com/v21.0/${igUserId}/media`,
              body: {
                media_type: 'CAROUSEL',
                children: childIds.join(','),
                caption,
                access_token: accessToken,
              },
              json: true,
            });

            if (carouselContainer && carouselContainer.id) {
              const publishRes = await this.helpers.httpRequest({
                method: 'POST',
                url: `https://graph.facebook.com/v21.0/${igUserId}/media_publish`,
                body: {
                  creation_id: carouselContainer.id,
                  access_token: accessToken,
                },
                json: true,
              });
              igMediaId = publishRes.id || null;
            }
          }
        }
      } catch (err) {
        errors.push(`Instagram (${batch.city}): ${err.message || String(err)}`);
      }
    }
  }

  const callbackPayload = {
    difusion_ids: batch.diffusionIds,
    difusion_id: batch.diffusionIds[0],
    ciudad: batch.city,
    network: 'meta',
    estado: errors.length > 0 && !fbPostId && !igMediaId ? 'error' : 'publicado',
    fb_post_id: fbPostId,
    ig_media_id: igMediaId,
    error: errors.length > 0 ? errors.join(' | ') : null,
  };

  if (batch.callbackUrl) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: batch.callbackUrl,
        headers: {
          'X-Webhook-Secret': webhookSecret,
          'Content-Type': 'application/json',
        },
        body: callbackPayload,
        json: true,
      });
    } catch (cbErr) {
      errors.push(`Callback Error: ${cbErr.message || String(cbErr)}`);
    }
  }

  results.push({
    json: {
      city: batch.city,
      totalPublished: batch.diffusionIds.length,
      fb_post_id: fbPostId,
      ig_media_id: igMediaId,
      errors,
    },
  });
}

return results;
